func (engine *Engine) createContext(w http.ResponseWriter, req *http.Request, params httprouter.Params, handlers []HandlerFunc) *Context {
	select {
	case c := <-engine.cache:
		c.Writer.reset(w)
		c.Req = req
		c.Params = params
		c.handlers = handlers
		c.Keys = nil
		c.index = -1
		return c
	default:
		return &Context{
			Writer:   &responseWriter{w, -1, false},
			Req:      req,
			Params:   params,
			handlers: handlers,
			index:    -1,
			Engine:   engine,
		}
